templates.body:
name: streamscope
version: 0.0.1
schema: v1
models:
{{#each routes}}  - name: {{model_alias}}
    provider: anthropic
    model: {{model_alias}}
    apiBase: {{{base_url}}}/v1/
    apiKey: {{{../api_key}}}
    roles:
      - chat
      - edit
      - apply
{{#if supports_vision}}    capabilities:
      - image_input
{{#if supports_function_calling}}      - tool_use
{{/if}}{{else}}{{#if supports_function_calling}}    capabilities:
      - tool_use
{{/if}}{{/if}}{{#if context_window}}    contextLength: {{context_window}}
{{/if}}{{#if max_output_tokens}}    defaultCompletionOptions:
      maxTokens: {{max_output_tokens}}
{{/if}}{{/each}}{{#if mcp_servers}}mcpServers:
{{#each mcp_servers}}  - name: {{quoted slug}}
{{#if local}}    type: stdio
    command: {{quoted command}}
{{#if args}}    args:
{{#each args}}      - {{quoted value}}
{{/each}}{{/if}}{{#if env}}    env:
{{#each env}}      {{name}}: {{quoted value}}
{{/each}}{{/if}}{{else}}    type: streamable-http
    url: {{quoted url}}
{{#if headers}}    requestOptions:
      headers:
{{#each headers}}        {{name}}: {{quoted value}}
{{/each}}{{/if}}{{/if}}{{/each}}{{/if}}

